      <EmptyState v-if="loaded && !data.changes.length" icon="GitBranch" title="尚无可靠变更" description="先配置应用目标和 HTTP 健康检查，再审阅准备好的镜像。" />
      <section v-for="change in data.changes" :key="change.id" class="section-panel p-4 min-w-0" :aria-label="'变更 ' + change.review.projectName">
        <div class="flex flex-wrap justify-between gap-2"><h3 class="font-semibold">{{ change.review.projectName }} / {{ change.review.serviceName }}</h3><span class="text-sm" :class="tone(change.status)">{{ label(change.status) }}</span></div>
        <p class="mt-2 text-xs text-surface-400">{{ change.hostId }} · {{ time(change.createdAt) }} · {{ change.approvedBy ? `批准人 ${change.approvedBy}` : '尚未批准' }}</p>
        <dl class="mt-3 space-y-2 text-xs break-all"><div><dt class="text-surface-400">原镜像 ID</dt><dd class="mt-1 font-mono">{{ change.review.old.imageId }}</dd></div><div><dt class="text-surface-400">新镜像 ID（{{ change.review.next.requested }}）</dt><dd class="mt-1 font-mono">{{ change.review.next.imageId }}</dd></div></dl>
        <p v-if="change.error" class="mt-3 text-sm text-status-warn">{{ change.error }}</p>
        <p v-if="change.result.forwardVerification" class="mt-3 text-sm">新镜像 HTTP 验收：{{ change.result.forwardVerification.passed ? '通过' : '未通过' }}</p><p v-if="change.result.rollbackVerification" class="mt-2 text-sm">原镜像回退验收：{{ change.result.rollbackVerification.passed ? '通过' : '未通过' }}</p>
        <div class="mt-4 flex flex-wrap gap-2"><button v-if="change.status === 'reviewed'" class="btn-primary btn-sm" :disabled="busy" @click="approval = { change: clone(change), allowRollback: false }">审阅并批准变更</button><button v-if="['reviewed','queued'].includes(change.status)" class="btn-secondary btn-sm" :disabled="busy" @click="act(() => api.sreOperation(`changes/${change.id}/cancel`), '变更已取消。')">取消变更</button><button v-if="change.status === 'outcome_unknown'" class="btn-secondary btn-sm" :disabled="busy" @click="acknowledgement = { path: `changes/${change.id}/acknowledge`, title: change.review.projectName, reason: '' }">核对未知结果</button><router-link class="btn-secondary btn-sm" :to="{ path: '/logs', query: { projectId: change.projectId, hostId: change.hostId, from: 'reliability' } }">应用日志</router-link></div>
        <details class="mt-3 text-xs text-surface-400"><summary class="cursor-pointer">配置指纹与执行证据</summary><pre class="mt-2 max-h-72 overflow-auto whitespace-pre-wrap break-all">{{ JSON.stringify({ review: change.review, result: change.result }, null, 2) }}</pre></details>
      </section>
    </template>
    <template v-else-if="tab === 'recovery'">
      <section class="section-panel p-4"><div class="flex flex-wrap justify-between items-center gap-3"><div><h2 class="font-semibold">应用恢复计划</h2><p class="mt-2 text-sm text-surface-400">选择需保护的数据卷，设定恢复点年龄与隔离还原用时目标。</p></div><button class="btn-primary" :disabled="busy" @click="editPlan()">新建恢复计划</button></div><p class="mt-3 text-xs text-status-warn">演练将已有归档还原到临时卷，并验证文件及清理结果。它不启动数据库，不证明业务一致性，也不覆盖绑定挂载或外部服务。</p></section>
      <EmptyState v-if="loaded && !data.recoveryPlans.length" icon="Database" title="尚无恢复计划" description="已有卷备份可直接纳入隔离演练，先检查备份覆盖再配置定期验证。" />
      <section v-for="plan in data.recoveryPlans" :key="plan.id" class="section-panel p-4 min-w-0"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-semibold">{{ plan.projectName }} · {{ plan.hostId }}</h3><span class="text-sm">{{ plan.enabled ? '已启用' : '已暂停' }} · v{{ plan.version }}</span></div><p class="mt-3 text-sm break-all">{{ plan.config.volumes.join('、') }}</p><p class="mt-2 text-xs text-surface-400">选择 {{ plan.config.volumes.length }} / {{ plan.config.declaredVolumes.length }} 个命名卷 · 备份年龄不超过 {{ plan.config.rpoMinutes }} 分钟 · 隔离还原不超过 {{ plan.config.rtoMinutes }} 分钟</p><p class="mt-2 text-xs text-surface-400">{{ plan.nextRunAt ? `下次定时演练 ${time(plan.nextRunAt)}` : '仅手动触发' }} · {{ plan.config.excluded.length }} 项挂载未覆盖</p><div class="mt-4 flex flex-wrap gap-2"><button class="btn-primary btn-sm" :disabled="busy || !plan.enabled" @click="act(() => api.sreOperation(`recovery/plans/${plan.id}/run`), '隔离演练已入队，可在下方追踪。')">运行隔离演练</button><button class="btn-secondary btn-sm" :disabled="busy" @click="editPlan(plan)">编辑恢复计划</button><button v-if="plan.enabled" class="btn-secondary btn-sm" :disabled="busy" @click="act(() => api.sreOperation(`recovery/plans/${plan.id}/pause`), '计划已暂停，尚未开始的演练将停止。')">暂停计划</button><router-link class="btn-secondary btn-sm" :to="{ path: '/resources', query: { tab: 'backups', projectId: plan.projectId, hostId: plan.hostId, from: 'reliability' } }">查看备份</router-link></div></section>
      <h2 class="pt-2 font-semibold">演练记录</h2>
