    </template>
    <template v-else>
      <section class="section-panel p-4"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-semibold">基于证据的复盘</h2><p class="mt-2 text-sm text-surface-400">从真实观测、故障、变更与演练记录提炼建议；每条分析保留引用。</p></div><button class="btn-primary" :disabled="busy" @click="act(() => api.sreOperation('retrospectives'), '复盘请求已完成，请查看下方结果。')">{{ busy ? '正在生成…' : '生成 AI 复盘' }}</button></div><p class="mt-3 text-xs text-status-warn">AI 建议需要人工核验。生成复盘不会修改自动授权或执行任何处置。</p><div class="mt-3 grid gap-3 sm:grid-cols-2"><div><h3 class="text-xs text-surface-400">最近 30 天变更结果</h3><p class="mt-1 text-sm">{{ outcomes(data.insights.changeOutcomes) }}</p></div><div><h3 class="text-xs text-surface-400">最近 30 天演练结果</h3><p class="mt-1 text-sm">{{ outcomes(data.insights.drillOutcomes) }}</p></div></div></section>
      <EmptyState v-if="loaded && !data.retrospectives.length" icon="FileSearch" title="尚无复盘" description="积累真实记录后生成复盘；少量样本会明确标注局限。" />
      <section v-for="report in data.retrospectives" :key="report.id" class="section-panel p-4"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-semibold">{{ time(report.createdAt) }}</h3><span :class="tone(report.status)">{{ label(report.status) }}</span></div><p v-if="report.error" class="mt-3 text-status-warn text-sm">{{ report.error }}</p><p class="mt-3 text-xs text-surface-400">{{ report.evidence.selection }}</p><p v-if="report.content" class="mt-2 text-xs text-surface-400">{{ report.content.interpretation }}</p><ol class="mt-4 space-y-4"><li v-for="(finding, i) in report.content?.findings || []" :key="i" class="border-l-2 border-surface-700 pl-3"><p class="text-sm leading-6">{{ finding.claim }}</p><p class="mt-2 text-xs leading-6 text-surface-400">建议：{{ finding.recommendation }}</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="key in finding.evidenceIds" :key="key" class="text-link text-xs break-all text-left" @click="source = report.evidence.sources.find(s => s.id === key)">查看证据 {{ key }}</button></div></li></ol></section>
    </template>
    <BaseModal :show="!!changeDraft" title="评审固定镜像变更" :close-disabled="busy" @close="changeDraft = null"><form v-if="changeDraft" class="space-y-4" @submit.prevent="review"><fieldset class="space-y-4" :disabled="busy"><label class="form-grid-label"><span>应用目标</span><select v-model="changeDraft.profileId" class="input w-full" required><option v-for="p in profiles.filter(p => p.enabled)" :key="p.id" :value="p.id">{{ p.projectName }} / {{ p.serviceName }} · {{ p.hostId }}</option></select></label><label class="form-grid-label"><span>已准备的新镜像</span><input v-model.trim="changeDraft.image" class="input w-full" placeholder="registry/app:version 或完整镜像 ID" required /></label><p class="text-xs text-surface-400">评审读取节点现有镜像并固定完整 ID。此步骤不改变运行服务；稍后单独批准。</p><p v-if="formError" class="alert-error">{{ formError }}</p><button class="btn-primary" type="submit">生成变更评审</button></fieldset></form></BaseModal>
    <ConfirmDialog :show="!!approval" title="批准固定镜像变更" confirm-text="批准并执行" tone="warning" :busy="busy" :message="approval ? `${approval.change.review.projectName} / ${approval.change.review.serviceName} · ${approval.change.hostId}` : ''" @cancel="approval = null" @confirm="approve"><template v-if="approval"><p class="text-xs break-all">原镜像：{{ approval.change.review.old.imageId }}<br />新镜像：{{ approval.change.review.next.imageId }}</p><p class="mt-2 text-xs leading-6">更新会重建该服务容器并可能短暂中断。HTTP 连续观测通过后才完成；中断或身份变化会停止自动操作。</p><label class="mt-3 flex items-start gap-2 text-sm"><input v-model="approval.allowRollback" class="mt-1" type="checkbox" :disabled="busy" /><span>授权验收失败时自动恢复上述原镜像。{{ approval.change.review.rollbackScope }}</span></label><p v-if="formError" class="alert-error">{{ formError }}</p></template></ConfirmDialog>
    <BaseModal :show="!!planDraft" :title="planDraft?.id ? '编辑应用恢复计划' : '新建应用恢复计划'" :close-disabled="busy" @close="planDraft = null"><form v-if="planDraft" class="space-y-4" @submit.prevent="savePlan"><fieldset class="space-y-4" :disabled="busy"><label v-if="!planDraft.id" class="form-grid-label"><span>纳管应用</span><select v-model="targetKey" class="input w-full" required @change="chooseTarget"><option disabled value="">选择应用与节点</option><option v-for="target in targets" :key="target.hostId + ':' + target.projectId" :value="target.hostId + ':' + target.projectId">{{ target.projectName }} · {{ target.hostId }}</option></select></label><p v-else class="text-sm">{{ planDraft.projectName }} · {{ planDraft.hostId }}</p><p v-if="candidatesLoading" class="text-xs">正在核对完整配置与命名卷…</p><fieldset class="space-y-2"><legend class="text-sm mb-2">纳入演练的命名卷</legend><label v-for="volume in candidates.volumes" :key="volume" class="flex gap-2 text-sm break-all"><input v-model="planDraft.volumes" type="checkbox" :value="volume" />{{ volume }}</label><p v-if="!candidatesLoading && !candidates.volumes.length" class="text-xs text-status-warn">尚无可选择的命名卷。</p></fieldset><p v-if="candidates.excluded.length" class="text-xs text-status-warn">{{ candidates.excluded.length }} 项挂载未纳入，详情保存在计划与演练证据中。</p><div class="grid grid-cols-2 gap-3"><label class="form-grid-label"><span>备份年龄目标（分钟）</span><input v-model.number="planDraft.rpoMinutes" class="input w-full" type="number" min="1" max="43200" required /></label><label class="form-grid-label"><span>还原用时目标（分钟）</span><input v-model.number="planDraft.rtoMinutes" class="input w-full" type="number" min="1" max="120" required /></label></div><label class="form-grid-label"><span>演练频率</span><select v-model.number="planDraft.scheduleHours" class="input w-full"><option :value="0">仅手动</option><option :value="24">每天</option><option :value="168">每周</option><option :value="720">每 30 天</option></select></label><label v-if="planDraft.scheduleHours" class="flex gap-2 text-sm"><input v-model="scheduleConfirmed" type="checkbox" required />授权按此频率创建临时容器和卷进行隔离演练</label><label class="flex gap-2 text-sm"><input v-model="planDraft.enabled" type="checkbox" />启用计划</label><p v-if="formError" class="alert-error">{{ formError }}</p><button class="btn-primary" type="submit" :disabled="candidatesLoading || !planDraft.volumes.length">保存恢复计划</button></fieldset></form></BaseModal>
    <BaseModal :show="!!acknowledgement" title="核对并关闭未知结果" :close-disabled="busy" @close="acknowledgement = null"><form v-if="acknowledgement" class="space-y-4" @submit.prevent="acknowledge"><p class="text-sm">{{ acknowledgement.title }}。请核对原节点的镜像、进程、挂载及临时资源；关闭只解除待核对状态，不会把未知改成成功。</p><label class="form-grid-label"><span>实际检查结果与处理说明</span><textarea v-model.trim="acknowledgement.reason" class="input w-full" rows="4" minlength="8" maxlength="1000" required :disabled="busy" /></label><p v-if="formError" class="alert-error">{{ formError }}</p><button class="btn-primary" type="submit" :disabled="busy">提交核对记录</button></form></BaseModal>
    <BaseModal :show="!!source" title="复盘引用的原始证据" @close="source = null"><pre class="text-xs max-h-96 overflow-auto whitespace-pre-wrap break-all">{{ JSON.stringify(source, null, 2) }}</pre><router-link v-if="source?.kind === 'incident'" class="btn-secondary mt-3" :to="{ path: '/oncall', query: { incident: source.sourceId, from: 'reliability' } }">打开故障事件</router-link></BaseModal>
  </div>
</template>
<script setup>
import { ref, onMounted, onActivated, onDeactivated, onBeforeUnmount } from 'vue';
import { api } from '../api/client.js';
import BaseModal from './common/BaseModal.vue';
import ConfirmDialog from './common/ConfirmDialog.vue';
import EmptyState from './common/EmptyState.vue';
defineProps({ tab: { type: String, required: true }, profiles: { type: Array, default: () => [] } });
const data = ref({ changes: [], recoveryPlans: [], recoveryRuns: [], retrospectives: [], insights: {} });
const error = ref(''), notice = ref(''), formError = ref(''), loading = ref(false), loaded = ref(false), busy = ref(false);
const acknowledgement = ref(null);
const changeDraft = ref(null), approval = ref(null), planDraft = ref(null), targets = ref([]), targetKey = ref(''), candidates = ref({ volumes: [], excluded: [] }), candidatesLoading = ref(false), scheduleConfirmed = ref(false), source = ref(null);
let active = false, disposed = false, generation = 0, selection = 0, timer, controller, selectionController;
const clone = value => JSON.parse(JSON.stringify(value));
const time = value => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '暂无';
const duration = value => value == null ? '待统计' : (value / 60000).toFixed(1) + ' 分钟';
const label = value => ({ closed: '人工关闭（未验收）', reviewed: '待审批', queued: '等待执行', checking: '执行前核对', executing: '正在更新', verifying: '正在验收', rolling_back: '正在回退', verifying_rollback: '正在验收回退', succeeded: '变更已验收', rolled_back: '原镜像已恢复并验收', failed: '未通过', rollback_failed: '回退未通过', outcome_unknown: '结果未知，需要核对', blocked: '执行前已阻止', cancelled: '已取消', passed: '隔离演练达标', running: '正在演练', verified: '归档解包已验证', empty: '空归档', missing: '缺少备份', ready: '复盘已生成', generating: '正在生成' })[value] || '待验证';
const tone = value => ['succeeded','passed','verified','ready'].includes(value) ? 'text-status-ok' : ['failed','rollback_failed','outcome_unknown','blocked','rolled_back'].includes(value) ? 'text-status-warn' : 'text-surface-300';
const outcomes = value => Object.entries(value || {}).map(([key, count]) => `${label(key)} ${count} 次`).join(' · ') || '暂无样本';
async function load() {
  if (!active || loading.value) return;
  const current = ++generation; controller = new AbortController(); loading.value = true;
  try { const result = await api.getSreOperations(controller.signal); if (active && current === generation) { data.value = { changes: [], recoveryPlans: [], recoveryRuns: [], retrospectives: [], insights: {}, ...result }; loaded.value = true; error.value = ''; } }
  catch (cause) { if (active && current === generation) error.value = cause.message || '记录加载失败'; }
  finally { if (current === generation) loading.value = false; }
}
async function act(action, message, done = () => {}) {
  if (busy.value) return; busy.value = true; formError.value = ''; notice.value = '';
  try { const result = await action(); if (!disposed) { done(result); notice.value = message; controller?.abort(); generation++; loading.value = false; await load(); } }
  catch (cause) { if (!disposed) { formError.value = cause.message || '操作未完成'; error.value = formError.value; } }
  finally { if (!disposed) busy.value = false; }
}
function acknowledge() { const value = clone(acknowledgement.value); return act(() => api.sreOperation(value.path, { reason: value.reason }), '核对记录已保存，未知结果未计入成功。', () => { acknowledgement.value = null; }); }
function review() { const payload = clone(changeDraft.value); return act(() => api.sreOperation('changes/review', payload), '评审已生成，请核对后单独批准。', () => { changeDraft.value = null; }); }
function approve() { const current = clone(approval.value); return act(() => api.sreOperation(`changes/${current.change.id}/approve`, { confirm: 'APPLY_PINNED_IMAGE', fingerprint: current.change.fingerprint, allowRollback: current.allowRollback }), '变更已批准并入队。', () => { approval.value = null; }); }
async function editPlan(plan) {
  formError.value = ''; targetKey.value = ''; scheduleConfirmed.value = false;
  planDraft.value = plan ? { id: plan.id, version: plan.version, hostId: plan.hostId, projectId: plan.projectId, projectName: plan.projectName, enabled: plan.enabled, ...clone(plan.config) } : { volumes: [], rpoMinutes: 1440, rtoMinutes: 30, scheduleHours: 0, enabled: true };
  candidates.value = { volumes: [], excluded: [] };
  if (plan) return readCandidates();
  const current = ++selection; selectionController?.abort(); selectionController = new AbortController();
  try { const result = await api.getSreTargets(selectionController.signal); if (active && current === selection) targets.value = (result.targets || []).filter(target => target.editable !== false); }
  catch (cause) { if (active && current === selection) formError.value = cause.message; }
}
function chooseTarget() { const target = targets.value.find(item => item.hostId + ':' + item.projectId === targetKey.value); if (target && planDraft.value) { Object.assign(planDraft.value, { ...target, volumes: [] }); void readCandidates(); } }
async function readCandidates() {
  const current = ++selection, draft = planDraft.value; selectionController?.abort(); selectionController = new AbortController(); candidatesLoading.value = true; candidates.value = { volumes: [], excluded: [] };
  try { const result = await api.getRecoveryCandidates({ hostId: draft.hostId, projectId: draft.projectId }, selectionController.signal); if (active && current === selection && draft === planDraft.value) { candidates.value = result; draft.volumes = draft.volumes.filter(volume => result.volumes.includes(volume)); } }
  catch (cause) { if (active && current === selection) formError.value = cause.message; }
  finally { if (current === selection) candidatesLoading.value = false; }
}
function savePlan() { const value = clone(planDraft.value); if (value.scheduleHours && !scheduleConfirmed.value) { formError.value = '请明确授权定时演练'; return; } value.confirm = value.scheduleHours ? 'ENABLE_RECOVERY_SCHEDULE' : ''; return act(() => api.sreOperation('recovery/plans' + (value.id ? '/' + value.id : ''), value, value.id ? 'PUT' : 'POST'), '恢复计划已保存。', () => { planDraft.value = null; }); }
function start() { if (active || disposed) return; active = true; void load(); timer = setInterval(() => { if (!busy.value) void load(); }, 10000); }
function stop() { active = false; clearInterval(timer); controller?.abort(); selectionController?.abort(); generation++; selection++; loading.value = false; candidatesLoading.value = false; }
onMounted(start); onActivated(start); onDeactivated(stop); onBeforeUnmount(() => { disposed = true; stop(); });
</script>
